SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, account_id, CASE WHEN amount >= 4300 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, MIN(txn_time) AS started_at, COUNT(*) FILTER (WHERE txn_type = 'CREDIT') AS credit_rows, MAX(txn_time) AS ended_at, GROUPING_ID() AS grouping_level FROM transactions GROUP BY CUBE (DATE_TRUNC('MONTH', txn_time), account_id, CASE WHEN amount >= 4300 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY account_id DESC;
